  "study.quality": ["IMU: {samples} rekordów · utracone: {drops} · błędy zapisu: {failed} · luka źródłowa p95: {gap} s", "IMU: {samples} records · dropped: {drops} · write failures: {failed} · source gap p95: {gap} s", "IMU: {samples} Datensätze · verworfen: {drops} · Schreibfehler: {failed} · Quelllücke p95: {gap} s"],
  "study.contextDifferent": ["Warunki A i B różnią się lub nie zostały opisane jednakowo. Porównanie nie izoluje wpływu samego profilu.", "A and B conditions differ or are not described equally. The comparison does not isolate profile effects.", "Bedingungen A/B weichen ab oder sind unterschiedlich beschrieben. Der Vergleich isoliert den Profileinfluss nicht."],
  "study.noData": ["Brak zapisanych zdarzeń i pomiarów. Rozpocznij kolekcję albo wybierz inną sesję.", "No saved events or observations. Start a collection or choose another session.", "Keine gespeicherten Ereignisse oder Messungen. Sammlung starten oder andere Sitzung wählen."],
  "study.noSample": ["Brak próbki w tej chwili", "No sample at this time", "Keine Probe zu diesem Zeitpunkt"],
  "study.previous": ["Poprzednia próbka / zdarzenie", "Previous sample / event", "Vorherige Probe / Ereignis"],
  "study.next": ["Następna próbka / zdarzenie", "Next sample / event", "Nächste Probe / Ereignis"],
  "study.time": ["Kursor czasu odbioru", "Reception time cursor", "Empfangszeitcursor"],
  "study.window": ["Okno czasu", "Time window", "Zeitfenster"],
  "study.all": ["Cała sesja", "Entire session", "Gesamte Sitzung"],
  "study.acceleration": ["Przyspieszenia osi 1/2/3 — wartości źródłowe z grawitacją", "Axes 1/2/3 acceleration — source values including gravity", "Beschleunigung der Achsen 1/2/3 — Quellwerte mit Schwerkraft"],
  "study.limits": ["Punkty to zachowane odczyty, nie ciągły pomiar. Luki nie są interpolowane; mało próbek może uniemożliwić porównanie. ACK i SDK ZERO nie dowodzą ruchu ani postoju. Brak pomiaru prędkości i drogi.", "Points are retained observations, not continuous measurement. Gaps are not interpolated; sparse data can prevent comparison. ACK and SDK ZERO prove neither motion nor stillness. No speed or distance measurement.", "Punkte sind erhaltene Messungen, keine kontinuierliche Messung. Lücken werden nicht interpoliert; spärliche Daten können einen Vergleich verhindern. ACK und SDK ZERO beweisen weder Bewegung noch Stillstand. Keine Geschwindigkeits- oder Wegmessung."],
  "study.noProfile": ["Brak profilu przypisanego do tej chwili. Aktualne ustawienia nie zastępują brakujących danych archiwalnych.", "No profile associated with this time. Current settings do not replace missing archived data.", "Kein Profil für diesen Zeitpunkt. Aktuelle Einstellungen ersetzen keine fehlenden Archivdaten."],
  "study.savedSettings": ["Próba używa zapisanych ustawień Pi. Szkic formularza nie został zastosowany.", "The trial uses saved Pi settings. The form draft has not been applied.", "Der Versuch nutzt gespeicherte Pi-Einstellungen. Der Formularentwurf wurde nicht angewendet."],
  "timing.title": ["Częstotliwości i zasoby", "Frequencies and resources", "Frequenzen und Ressourcen"],
  "timing.hint": ["Profil odświeżania Venoma. Wartości w Hz to cele wynikające z interwałów, nie zmierzone próbkowanie robota.", "Venom refresh profile. Hz values are interval targets, not measured robot sampling.", "Venom-Aktualisierungsprofil. Hz-Werte sind Intervallziele, keine gemessene Roboterabtastung."],
