  operatorPaused: ["Automat w pauzie; kamera i analiza pozostają aktywne.", "Automatic control paused; camera and analysis remain active.", "Automatik pausiert; Kamera und Analyse bleiben aktiv."],
  manualGestureReady: ["Strzałka przejmuje sterowanie ręczne jednym gestem.", "An arrow takes manual control in one gesture.", "Eine Pfeiltaste übernimmt mit einer Eingabe die manuelle Steuerung."],
  manualGestureHint: ["Nowy kierunek kończy automat. STOP i zwolnienie mają pierwszeństwo.", "A new direction ends automation. STOP and release take priority.", "Eine neue Richtung beendet die Automatik. STOP und Loslassen haben Vorrang."],
  manualGestureUnsupported: ["Pi wymaga aktualizacji do przejęcia strzałką. Użyj Przejmij ręcznie.", "Pi needs an update for arrow takeover. Use Take manual control.", "Pi benötigt ein Update für die Übernahme per Pfeiltaste. Manuell übernehmen verwenden."],
