  "trial.error.navigation_trial_prepare_timeout": ["Przekroczono limit przygotowania usług lub końcowego startu. Próba nie została potwierdzona.","Service preparation or final startup exceeded its limit. The trial was not confirmed.","Dienstvorbereitung oder abschließender Start überschritt das Zeitlimit. Der Versuch wurde nicht bestätigt."],
  "trial.error.navigation_trial_authority_changed": ["Sterowanie zmieniło właściciela podczas przygotowania. Ten start został anulowany.","Control ownership changed during preparation. This start was cancelled.","Steuerung wechselte während der Vorbereitung. Dieser Start wurde abgebrochen."],
  "trial.error.navigation_trial_replay": ["To żądanie startu zostało już obsłużone. Kolejna próba wymaga nowego kliknięcia „Start · 10 s”.", "This start request was already handled. Click “Start · 10 s” again for another trial.", "Diese Startanfrage wurde bereits bearbeitet. Für einen neuen Versuch erneut „Start · 10 s“ klicken."],
  "trial.error.navigation_trial_journal_unavailable": ["Pi nie może zapisać stanu próby. Jazda nie została rozpoczęta.","Pi cannot record the trial state. Driving was not started.","Pi kann den Versuchszustand nicht speichern. Die Fahrt wurde nicht gestartet."],
  "trial.error.navigation_trial_stopped": ["Próba zakończyła się przed potwierdzeniem startu. Sprawdź zapisany powód zatrzymania.","The trial ended before start confirmation. Check its recorded stop reason.","Der Versuch endete vor der Startbestätigung. Gespeicherten Stoppgrund prüfen."],
  "trial.error.navigation_trial_arm_unconfirmed": ["Pi nie potwierdziło uprawnienia do tej próby. Sprawdź stan wykonawcy.","Pi did not confirm permission for this trial. Check executor status.","Pi hat die Freigabe für diesen Versuch nicht bestätigt. Ausführungsstatus prüfen."],
  "trial.error.navigation_trial_authority_unknown": ["Stan uprawnienia Pi jest nieznany. Start nie został potwierdzony.","Pi permission state is unknown. Start was not confirmed.","Pi-Freigabe ist unbekannt. Start wurde nicht bestätigt."],
  stopZone: ["Strefa STOP", "STOP zone", "STOP-Bereich"],
