  perceptionDeviation: ["Odchylenia", "Deviations", "Abweichungen"],
  perceptionGeometryHint: ["Ocena względnej geometrii, bez pomiaru centymetrów. Jazda tylko w nadzorowanym teście po potwierdzeniu strefy i hamowania; GO obrazu samo nie uzbraja Pi.", "Relative geometry assessment, without centimetre measurements. Driving is limited to a supervised trial after zone and braking acceptance; image GO alone does not arm Pi.", "Relative Geometriebewertung ohne Zentimetermessung. Fahrt nur als beaufsichtigter Versuch nach Bereichs- und Bremsabnahme; Bild-GO allein gibt Pi nicht frei."],
  perceptionPiUpdate: ["Regulacja percepcji wymaga nowego kontraktu konfiguracji Pi; bieżące parametry ruchu pozostają dostępne.", "Perception tuning requires the updated Pi configuration contract; motion settings remain available.", "Wahrnehmungseinstellungen benötigen den neuen Pi-Konfigurationsvertrag; Bewegungseinstellungen bleiben verfügbar."],
  loopDepthObservation: ["Test jazdy niedostępny: aktywna metoda Depth Anything służy obecnie wyłącznie do analizy obrazu. Zielone GO nie uruchamia silników.", "Driving trial unavailable: the active Depth Anything method currently supports image analysis only. Green GO does not start the motors.", "Fahrversuch nicht verfügbar: Die aktive Depth-Anything-Methode unterstützt derzeit nur Bildanalyse. Grünes GO startet die Motoren nicht."],
  "vision.reason.depth_ground_orientation": ["Geometria nie potwierdza perspektywy podłoża w torze jazdy.", "Geometry does not confirm ground perspective in the path.", "Geometrie bestätigt keine Bodenperspektive im Fahrweg."],
  "vision.reason.depth_ground_deviation": ["W torze jazdy geometria odstaje od powierzchni podłoża.", "Geometry deviates from the ground surface in the path.", "Geometrie weicht im Fahrweg von der Bodenfläche ab."],
  "vision.reason.depth_plane_candidate": ["Geometria zgodna z płaskim podłożem; ocena eksperymentalna.", "Geometry matches flat ground; experimental assessment.", "Geometrie entspricht ebenem Boden; experimentelle Bewertung."],
  "vision.reason.depth_observation_only": ["Ta metoda ocenia obraz i nie wydaje komend ruchu.", "This method assesses images and issues no motion commands.", "Diese Methode bewertet Bilder und gibt keine Bewegungsbefehle aus."],

