  visionBusy: ["Model przetwarza klatkę. Podgląd ponowi odczyt.", "Model is processing a frame. Preview will retry.", "Modell verarbeitet ein Bild. Vorschau versucht es erneut."],
  visionPreviewUnavailable: ["Brak wyniku analizy obrazu. Sprawdź kamerę, konfigurację modelu i budżet czasu.", "No image analysis result. Check camera, model configuration and time budget.", "Kein Bildanalyseergebnis. Kamera, Modellkonfiguration und Zeitbudget prüfen."],
  visionVenom: ["Wizja Venom", "Venom vision", "Venom-Bildverarbeitung"],
  visionPi: ["Przetwarzanie na Pi", "Pi processing", "Pi-Bildverarbeitung"],
  visionLegend: ["Biała ramka: strefa STOP. Niebieska przerywana: odniesienie geometrii, poza strefą STOP. Klasy powierzchni: zielony podłoga, niebieski droga/chodnik/dywan, czerwony inna klasa. Geometria: zielony zgodność z podłożem, czerwony odchylenie. Żółty: niepewność.", "White box: STOP zone. Dashed blue: geometry reference, outside the STOP zone. Surface classes: green floor, blue road/sidewalk/rug, red another class. Geometry: green ground agreement, red deviation. Yellow: uncertainty.", "Weißer Rahmen: STOP-Bereich. Blau gestrichelt: Geometriereferenz außerhalb des STOP-Bereichs. Oberflächenklassen: Grün Boden, Blau Straße/Gehweg/Teppich, Rot andere Klasse. Geometrie: Grün Bodenübereinstimmung, Rot Abweichung. Gelb: Unsicherheit."],
  visionDefaultZone: ["Domyślna strefa podglądu; Pi nie ma jeszcze nowego API konfiguracji", "Default preview zone; Pi does not yet expose the new configuration API", "Standard-Vorschaubereich; Pi bietet die neue Konfigurations-API noch nicht"],
  "vision.clear": ["Kandydat wolnej drogi", "Clear path candidate", "Kandidat für freien Weg"],
  "vision.obstacle": ["Przeszkoda lub odchylenie w strefie", "Obstacle or deviation in zone", "Hindernis oder Abweichung im Bereich"],
  "vision.unknown": ["Niepewny wynik", "Uncertain result", "Unsicheres Ergebnis"],
  "loopTrialParameters": ["Parametry próby", "Trial parameters", "Versuchsparameter"],
  "loopCalibrationRevoke": ["Unieważnij odbiór — kamera lub warunki zmienione", "Revoke acceptance — camera or conditions changed", "Abnahme aufheben — Kamera oder Bedingungen geändert"],
  "loopCalibrationTitle": ["Przygotowanie i odbiór jazdy", "Driving setup and acceptance", "Fahrtvorbereitung und Abnahme"],
  "loopCalibrationAccepted": ["Kalibracja zapisana", "Calibration saved", "Kalibrierung gespeichert"],
  "loopCalibrationMissing": ["Brak odbioru kalibracji", "Calibration not accepted", "Kalibrierung nicht abgenommen"],
  "loopCalibrationMeaning": ["To odbiór operatora, nie automatyczny pomiar. Model rozpoznaje podłogę; nie mierzy odległości ani drogi hamowania.", "This is operator acceptance, not automatic measurement. The model identifies floor; it does not measure distance or braking distance.", "Dies ist eine Operatorabnahme, keine automatische Messung. Das Modell erkennt Boden; es misst weder Abstand noch Bremsweg."],
  "loopCalibrationStepPreview": ["Obraz i analiza", "Image and analysis", "Bild und Analyse"],
  "loopCalibrationPreviewHelp": ["Uruchom kamerę i analizę. Przełącz RAW / Wizja Venom i sprawdź, czy widać podłogę przed robotem.", "Start camera and analysis. Switch RAW / Venom vision and check that the floor ahead is visible.", "Kamera und Analyse starten. Zwischen RAW und Venom-Bild wechseln und den Boden vor dem Roboter prüfen."],
  "loopCalibrationStepZone": ["Strefa zatrzymania", "Stopping zone", "Stoppbereich"],
  "loopCalibrationZoneHelp": ["Biała ramka musi obejmować tor jazdy prosto przed robotem. Sprawdź pustą podłogę i przeszkodę: zielony oznacza podłogę, czerwony inną klasę, żółty niepewność.", "The white rectangle must cover the forward path ahead of the robot. Check empty floor and an obstacle: green means floor, red another class, yellow uncertainty.", "Der weiße Rahmen muss den Vorwärtsweg vor dem Roboter abdecken. Freien Boden und ein Hindernis prüfen: Grün bedeutet Boden, Rot andere Klasse, Gelb Unsicherheit."],
  "loopCalibrationEditZone": ["Dopasuj strefę i parametry", "Adjust zone and parameters", "Bereich und Parameter anpassen"],
  "loopCalibrationStepBrake": ["Ręczna próba hamowania", "Manual braking trial", "Manueller Bremsversuch"],
  "loopCalibrationBrakeHelp": ["Wykonaj ręczną próbę przy prędkości i maksymalnym impulsie z ustawień pętli. Potwierdź, że robot zatrzymuje się w widocznej strefie. Montaż kamery musi pozostać taki sam.", "Run a manual trial at the loop speed and maximum pulse from loop settings. Confirm stopping within the visible zone. Keep the same camera mounting.", "Manuellen Versuch mit Schleifengeschwindigkeit und maximalem Impuls aus den Schleifeneinstellungen durchführen. Anhalten im sichtbaren Bereich prüfen. Kameramontage unverändert lassen."],
  "loopCalibrationManualSettings": ["Ustawienia sterowania ręcznego", "Manual control settings", "Einstellungen der manuellen Steuerung"],
  "loopCalibrationZoneCheck": ["Sprawdziłem widoczny obraz i strefę dla pustej podłogi oraz przeszkody.", "I checked the visible image and zone with empty floor and an obstacle.", "Ich habe das sichtbare Bild und den Bereich bei freiem Boden und einem Hindernis geprüft."],
  "loopCalibrationNeedPreview": ["Najpierw pokaż świeży obraz „Wizja Venom”. Bez widocznej analizy nie można potwierdzić oceny strefy.", "Show a fresh Venom vision image first. Zone assessment cannot be confirmed without visible analysis.", "Zuerst ein aktuelles Venom-Bild anzeigen. Ohne sichtbare Analyse kann die Bereichsprüfung nicht bestätigt werden."],
  "loopCalibrationBrakeCheck": ["Wykonałem próbę ręczną i potwierdzam hamowanie dla tych parametrów oraz montażu kamery.", "I ran a manual trial and confirm braking for these parameters and camera mounting.", "Ich habe einen manuellen Versuch durchgeführt und bestätige das Bremsen für diese Parameter und Kameramontage."],
  "loopCalibrationAccept": ["Zapisz odbiór kalibracji na Pi", "Save calibration acceptance on Pi", "Kalibrierungsabnahme auf Pi speichern"],
  "loopCalibrationAcceptHelp": ["Zapis kończy obserwację. Model i identyfikator są uzupełniane automatycznie. Nie uzbraja ruchu ani nie uruchamia jazdy.", "Saving ends observation. Model and ID are filled automatically. It does not arm motion or start driving.", "Speichern beendet die Beobachtung. Modell und ID werden automatisch ergänzt. Bewegung wird nicht freigegeben und Fahrt nicht gestartet."],
  "loopCalibrationSettingsHelp": ["Zatrzymaj jazdę przed zapisaniem parametrów; samą obserwację panel przełączy podczas zapisu. Zmiana strefy, prędkości lub limitów czasu wymaga nowego odbioru. Po zmianie montażu kamery wykonaj odbiór ponownie.", "Stop driving before saving parameters; the panel handles observation during saving. Zone, speed or time-limit changes require new acceptance. Repeat acceptance after changing camera mounting.", "Fahrt vor dem Speichern der Parameter stoppen; das Panel steuert die Beobachtung beim Speichern. Änderungen an Bereich, Geschwindigkeit oder Zeitlimits erfordern neue Abnahme. Nach geänderter Kameramontage Abnahme wiederholen."],
  "loopObservationAvailable": ["Obserwacja dostępna", "Observation available", "Beobachtung verfügbar"],
